ALTER TABLE public.subscriptions ADD COLUMN provider text NOT NULL DEFAULT 'legacy', ADD COLUMN flutterwave_subscription_id text UNIQUE, ADD COLUMN next_billing_date timestamptz;
COMMENT ON COLUMN public.subscriptions.paddle_subscription_id IS 'DEPRECATED: historical provider ID; new records use an internal flw_ reference';
COMMENT ON COLUMN public.subscriptions.paddle_customer_id IS 'DEPRECATED: retained for subscription history';
CREATE TABLE public.flutterwave_checkouts (tx_ref text PRIMARY KEY, user_id uuid NOT NULL, tier text NOT NULL CHECK (tier IN ('monthly','annual')), amount numeric NOT NULL, currency text NOT NULL DEFAULT 'USD', plan_id text NOT NULL, environment text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.flutterwave_checkouts TO authenticated;
GRANT ALL ON public.flutterwave_checkouts TO service_role;
ALTER TABLE public.flutterwave_checkouts ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_read ON public.flutterwave_checkouts FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE TABLE public.flutterwave_transactions (transaction_id text PRIMARY KEY, user_id uuid NOT NULL, tx_ref text NOT NULL, subscription_id uuid NOT NULL REFERENCES public.subscriptions(id), paid_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.flutterwave_transactions TO authenticated;
GRANT ALL ON public.flutterwave_transactions TO service_role;
ALTER TABLE public.flutterwave_transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY owner_read ON public.flutterwave_transactions FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.has_active_subscription(user_uuid uuid, check_env text DEFAULT 'live') RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS (SELECT 1 FROM public.subscriptions WHERE user_id=user_uuid AND environment=check_env AND ((status IN ('active','trialing','past_due','active_monthly','active_annual') AND (current_period_end IS NULL OR current_period_end>now())) OR (status='canceled' AND current_period_end>now()))) $$;
CREATE OR REPLACE FUNCTION public.apply_flutterwave_payment(_transaction_id text,_tx_ref text,_subscription_id text,_paid_at timestamptz,_next_billing_date timestamptz) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c public.flutterwave_checkouts; sid uuid; BEGIN SELECT * INTO c FROM public.flutterwave_checkouts WHERE tx_ref=_tx_ref; IF NOT FOUND THEN RAISE EXCEPTION 'Unknown checkout'; END IF; PERFORM pg_advisory_xact_lock(hashtext(_subscription_id)); IF EXISTS(SELECT 1 FROM public.flutterwave_transactions WHERE transaction_id=_transaction_id) THEN RETURN; END IF; INSERT INTO public.subscriptions(user_id,paddle_subscription_id,paddle_customer_id,product_id,price_id,status,current_period_start,current_period_end,environment,provider,flutterwave_subscription_id,next_billing_date) VALUES(c.user_id,'flw_'||_subscription_id,'flutterwave','ummverse_premium',CASE WHEN c.tier='annual' THEN 'premium_yearly' ELSE 'premium_monthly' END,CASE WHEN c.tier='annual' THEN 'active_annual' ELSE 'active_monthly' END,_paid_at,_next_billing_date,c.environment,'flutterwave',_subscription_id,_next_billing_date) ON CONFLICT(flutterwave_subscription_id) DO UPDATE SET status=EXCLUDED.status,current_period_start=EXCLUDED.current_period_start,current_period_end=GREATEST(public.subscriptions.current_period_end,EXCLUDED.current_period_end),next_billing_date=GREATEST(public.subscriptions.next_billing_date,EXCLUDED.next_billing_date),updated_at=now() WHERE public.subscriptions.user_id=EXCLUDED.user_id RETURNING id INTO sid; IF sid IS NULL THEN RAISE EXCEPTION 'Subscription ownership mismatch'; END IF; INSERT INTO public.flutterwave_transactions(transaction_id,user_id,tx_ref,subscription_id,paid_at) VALUES(_transaction_id,c.user_id,c.tx_ref,sid,_paid_at); END $$;
REVOKE ALL ON FUNCTION public.apply_flutterwave_payment(text,text,text,timestamptz,timestamptz) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.apply_flutterwave_payment(text,text,text,timestamptz,timestamptz) TO service_role;